from pathlib import Path
import json,collections
r=Path('/tmp/engine-candidate-demand-20261105')
for cell in [61,62]:
 files=list(r.glob(f'cell-{cell}-*.heapprofile'))
 if len(files)!=3:continue
 own=collections.Counter();inclusive=collections.Counter();stacks=collections.Counter()
 for p in files:
  d=json.load(open(p))
  def visit(n,stack):
   f=n['callFrame'];name=f"{f['functionName'] or '(anonymous)'} {f['url'].replace('/home/holo/line/','')}:{f['lineNumber']+1}"
   stack=stack+[name];size=n['selfSize'];own[name]+=size
   for fn in set(stack):inclusive[fn]+=size
   stacks[' > '.join(stack[-4:])]+=size
   for c in n['children']:visit(c,stack)
  visit(d['head'],[])
 total=sum(own.values());out={'cell':cell,'sampledBytes':total,'self':[{'function':k,'bytes':v,'pct':v/total*100} for k,v in own.most_common(30)],'inclusive':[{'function':k,'bytes':v,'pct':v/total*100} for k,v in inclusive.most_common(40)],'stacks':[{'stack':k,'bytes':v,'pct':v/total*100} for k,v in stacks.most_common(30)]}
 (r/f'heap-summary-{cell}.json').write_text(json.dumps(out,indent=2)+'\n')
 print('cell',cell,'estimated allocated MB',total/len(files)/1e6)
 for x in out['self'][:15]:print(round(x['pct'],2),x['function'])

