test='''    #[test]
    fn event_history_matches_every_forward_trace_snapshot() {
        use crate::line::{LineRef, push_line};
        let lines = LineRef::batch((-30..30).map(|i| {
            let x = i as f64 * 30.0;
            Line::new(i + 100, x, 10.0 + (i % 3) as f64 * 3.0,
                x + 40.0, 12.0, (i & 1) as i64, (i.rem_euclid(8)) as i64)
        }).collect());
        let mut grid = LineGrid::default();
        let mut cache = LineCellCache::default();
        for line in &lines {
            push_line(&mut grid, line, line.cells());
            cache.include_cells(line.cells());
        }
        let mut collisions = 0;
        let mut accelerated = 0;
        let mut broken = false;
        for (x, y, vx, vy) in [(0.0, 0.0, 0.4, 0.0), (-80.0, -50.0, 8.0, 4.0),
            (100.0, 1.0, -8.0, -4.0), (-400.0, 200.0, 40.0, -20.0), (-0.0, -0.0, 0.0, -0.0)] {
            let mut state = init_state(x, y, vx, vy);
            let mut actual = CollisionHistory::new();
            let mut expected = CollisionHistory::new();
            let mut history_cache = cache.clone();
            for frame in 1..=100 {
                let previous = state.clone();
                let mut events = Vec::new();
                let mut trace = CollisionTrace::new(frame);
                step_state(&mut state, &grid, &mut events, &mut cache, Some(&mut trace));
                broken |= state.fsu[RIDER_MOUNTED] != -1;
                collisions += events.len();
                accelerated += events.iter().filter(|e| lines[(e.1 - 70) as usize].is_acc).count();
                record_history(&previous, &events, frame, &mut actual, &mut history_cache);
                // Independent oracle: the forward solver's observed positions,
                // without replaying constraints or using its cell shortcuts.
                expected.begin_frame();
                let mut event = 0;
                for it in 0..ITERATE {
                    for &(index, _) in &COLLIDING_POINTS {
                        let k = (it * NENT + index) * 6;
                        let (x, y, vx, vy) = (trace.points[k], trace.points[k + 1], trace.points[k + 4], trace.points[k + 5]);
                        expected.record_point(crate::grid::cell_hash(x, y), frame, x, y, vx, vy);
                        while event < events.len() && events[event].0 == it as u8 && events[event].2 == index as i32 {
                            let (_, id, _, x, y) = events[event];
                            expected.record_point(crate::grid::cell_hash(x, y), frame, x, y, vx, vy);
                            expected.record_collision(id, frame);
                            event += 1;
                        }
                    }
                }
                assert_eq!(event, events.len());
                expected.finish_frame();
                if [1, 2, 17, 65, 100].contains(&frame) { actual.assert_identical(&expected); }
            }
            for retained in [1, 17, 64, 100] {
                let mut a = actual.clone(); let mut b = expected.clone();
                a.truncate(retained); b.truncate(retained);
                a.assert_identical(&b);
            }
        }
        assert!(collisions > 100 && accelerated > 0 && broken, "exercise repeated collisions, accelerators and broken bindings");
    }

'''
