from pathlib import Path
p=Path('scripts/lib/native_motion/src/engine.rs');s=p.read_text();marker='mod ownership_tests {\n';assert marker in s
s=s.replace(marker,marker+'''
    fn cache_bounds(arena: &mut EngineArena, handle: u32) -> [f64; 4] {
        arena.update_computed(handle);
        arena.lineages[arena.ver(handle as i32).lineage as usize].as_ref().unwrap().cache.geometry_bounds()
    }

    #[test]
    fn geometry_envelopes_follow_siblings_starts_and_detached_ownership() {
        let mut arena = EngineArena::new();
        let root = arena.create();
        let empty = cache_bounds(&mut arena, root);
        let wide = arena.add_line(root, 1, 0, -1000.0, 10.0, 2000.0, 10.0, 0);
        let wide_bounds = cache_bounds(&mut arena, wide);
        let narrow = arena.add_line(root, 2, 0, 0.0, 10.0, 30.0, 10.0, 0);
        let narrow_bounds = cache_bounds(&mut arena, narrow);
        assert!(narrow_bounds[0] > wide_bounds[0] && narrow_bounds[1] < wide_bounds[1]);
        assert_eq!(cache_bounds(&mut arena, root), empty);
        assert_eq!(cache_bounds(&mut arena, wide), wide_bounds);
        assert_eq!(cache_bounds(&mut arena, narrow), narrow_bounds);
        let reset = arena.set_start(narrow, 4.0, -12.0, 1.0, 0.0);
        assert_eq!(cache_bounds(&mut arena, reset), narrow_bounds);
        let detached = arena.detach(reset);
        assert_eq!(cache_bounds(&mut arena, detached), narrow_bounds);
        arena.free(root); arena.free(narrow); arena.free(reset);
        let far = arena.add_line(detached, 3, 0, 3000.0, 10.0, 3100.0, 10.0, 0);
        assert!(cache_bounds(&mut arena, far)[1] > wide_bounds[1]);
        assert_eq!(cache_bounds(&mut arena, detached), narrow_bounds);
        assert_eq!(cache_bounds(&mut arena, wide), wide_bounds);
        arena.free(detached); arena.free(far); arena.free(wide);
    }

    #[test]
    fn repeated_ids_keep_historical_grid_entries_outside_version_bounds() {
        let mut arena = EngineArena::new();
        let root = arena.create();
        let duplicate = arena.add_lines(root, vec![
            build_line(1, -50.0, 10.0, 100.0, 10.0, 0, 0),
            build_line(1, 1000.0, 10.0, 1100.0, 10.0, 0, 0),
        ]);
        let unbounded = [f64::NEG_INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::INFINITY];
        assert_eq!(cache_bounds(&mut arena, duplicate), unbounded);
        assert_eq!(cache_bounds(&mut arena, root), unbounded);
        // Undo removes the latest footprint for id 1. The older grid entries
        // still exist, even though this version originally had no geometry.
        let mut events = Vec::new();
        let mut count = 0;
        for frame in 1..40 { count += arena.events_into(root, frame, &mut events); }
        assert!(count > 0, "historical entries must still collide after undo");
        let detached = arena.detach(root);
        arena.free(duplicate); arena.free(root);
        assert_eq!(cache_bounds(&mut arena, detached), unbounded);
        let reset = arena.set_start(detached, 0.0, 0.0, 0.4, 0.0);
        assert_eq!(cache_bounds(&mut arena, reset), unbounded);
        let child = arena.add_line(detached, 2, 0, 2000.0, 10.0, 2100.0, 10.0, 0);
        assert_eq!(cache_bounds(&mut arena, child), unbounded);
        assert_eq!(cache_bounds(&mut arena, reset), unbounded);
        arena.free(detached); arena.free(reset); arena.free(child);
    }
''')
